import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { EmptyState } from "@/components/ui/primitives";
import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
import {
  listFolders,
  listMessages,
  getMailboxes,
} from "@/lib/actions-mail";
import { MailClient } from "@/components/customer/mail/MailClient";

export const dynamic = "force-dynamic";

export const metadata = { title: "Mail — Nxeon" };

export default async function MailPage() {
  await requireUser();

  let folders: MailFolder[] = [];
  let mailboxes: MailboxInfo[] = [];
  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
  let inboxPath = "INBOX";
  let failed = false;

  try {
    const [f, mb] = await Promise.all([listFolders(), getMailboxes()]);
    folders = f;
    mailboxes = Array.isArray(mb) ? mb : mb ? [mb] : [];
    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
    list = await listMessages(inboxPath, 1);
  } catch {
    failed = true;
  }

  if (failed || folders.length === 0) {
    return (
      <div className="mx-auto max-w-2xl pt-10">
        <EmptyState
          title="No mailbox connected"
          sub="We couldn't reach a mailbox for your account. Set up business email on one of your domains to start using webmail here."
          action={
            <Link href="/dashboard/email" className="btn-primary">
              Set up email
            </Link>
          }
        />
      </div>
    );
  }

  return (
    <MailClient
      initialFolders={folders}
      initialMailboxes={mailboxes}
      initialList={list}
      initialFolderPath={inboxPath}
    />
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import type {
  MailFolder,
  MailboxInfo,
  ListResult,
  MessageSummary,
  MessageFull,
  SendPayload,
} from "@/lib/mail/types";
import {
  listFolders,
  listMessages,
  getMessage,
  getMailboxes,
  sendMessage,
  setFlag,
  moveMessage,
  deleteMessage,
} from "@/lib/actions-mail";
import { FolderRail, type RailItem } from "./FolderRail";
import { MessageList } from "./MessageList";
import { ReadingPane } from "./ReadingPane";
import { ContactPanel } from "./ContactPanel";
import { Composer, type ComposeDraft } from "./Composer";
import { ShortcutHelp } from "./ShortcutHelp";
import { Icon, displayName, categoryOf, type MailTab } from "./util";

const STARRED = "__starred__";
const SNOOZED = "__snoozed__";

const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
  inbox: { label: "Inbox", icon: "inbox", order: 0 },
  sent: { label: "Sent", icon: "sent", order: 3 },
  drafts: { label: "Drafts", icon: "draft", order: 4 },
  junk: { label: "Spam", icon: "spam", order: 5 },
  trash: { label: "Trash", icon: "trash", order: 6 },
  archive: { label: "Archive", icon: "archive", order: 7 },
};

export function MailClient({
  initialFolders,
  initialMailboxes,
  initialList,
  initialFolderPath,
}: {
  initialFolders: MailFolder[];
  initialMailboxes: MailboxInfo[];
  initialList: ListResult;
  initialFolderPath: string;
}) {
  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
  const [activeAddress, setActiveAddress] = useState<string | undefined>(initialMailboxes[0]?.address);
  const [selected, setSelected] = useState<string>(initialFolderPath);
  const [list, setList] = useState<ListResult>(initialList);
  const [page, setPage] = useState(1);
  const [tab, setTab] = useState<MailTab>("primary");
  const [search, setSearch] = useState("");

  const [selectedUid, setSelectedUid] = useState<number | null>(null);
  const [cursorUid, setCursorUid] = useState<number | null>(null);
  const [message, setMessage] = useState<MessageFull | null>(null);
  const [msgLoading, setMsgLoading] = useState(false);

  const [draft, setDraft] = useState<ComposeDraft | null>(null);
  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
  const [railOpen, setRailOpen] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const [showHelp, setShowHelp] = useState(false);

  const [listPending, startList] = useTransition();
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;

  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
  const archivePath = folders.find((f) => f.role === "archive")?.path;
  const trashPath = folders.find((f) => f.role === "trash")?.path;

  /* ---- Rail model ------------------------------------------------------- */
  const byRole = (role: string) => folders.find((f) => f.role === role);
  const primaryItems: RailItem[] = [];
  const inbox = byRole("inbox");
  primaryItems.push({ key: inbox?.path ?? "INBOX", label: "Inbox", icon: "inbox", unread: inbox?.unread });
  primaryItems.push({ key: STARRED, label: "Starred", icon: "star", virtual: true });
  primaryItems.push({ key: SNOOZED, label: "Snoozed", icon: "clock", virtual: true });
  for (const role of ["sent", "drafts", "junk", "trash", "archive"] as const) {
    const f = byRole(role);
    const meta = ROLE_META[role];
    if (f) primaryItems.push({ key: f.path, label: meta.label, icon: meta.icon, unread: f.unread });
    else primaryItems.push({ key: `__missing_${role}`, label: meta.label, icon: meta.icon });
  }
  const customItems: RailItem[] = folders
    .filter((f) => f.role === "custom")
    .map((f) => ({ key: f.path, label: f.name, icon: "folder" as const, unread: f.unread }));

  const labelFor = useCallback(
    (key: string): string => {
      if (key === STARRED) return "Starred";
      if (key === SNOOZED) return "Snoozed";
      const f = folders.find((x) => x.path === key);
      if (f) return ROLE_META[f.role]?.label ?? f.name;
      return "Mailbox";
    },
    [folders]
  );

  const resolvePath = (key: string): string | null => {
    if (key === SNOOZED) return null;
    if (key === STARRED) return inboxPath;
    if (key.startsWith("__missing_")) return null;
    return key;
  };

  /* ---- Loading ---------------------------------------------------------- */
  const loadList = useCallback(
    (key: string, pageNum: number, q: string, addr = activeAddress) => {
      const path = resolvePath(key);
      if (path === null) {
        setList({ messages: [], total: 0, page: 1, pageSize: initialList.pageSize });
        return;
      }
      startList(async () => {
        try {
          const res = await listMessages(path, pageNum, q || undefined, addr);
          if (key === STARRED) {
            const flagged = res.messages.filter((m) => m.flagged);
            setList({ messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize });
          } else {
            setList(res);
          }
        } catch {
          setToast("Couldn't load messages.");
        }
      });
    },
    [inboxPath, initialList.pageSize, activeAddress]
  );

  const selectFolder = (key: string) => {
    setSelected(key);
    setPage(1);
    setRailOpen(false);
    setSelectedUid(null);
    setCursorUid(null);
    setMessage(null);
    setMobilePane("list");
    loadList(key, 1, search);
  };

  /* ---- Mailbox switching ------------------------------------------------ */
  const switchMailbox = async (address: string) => {
    if (address === activeAddress) return;
    setActiveAddress(address);
    setSelectedUid(null);
    setCursorUid(null);
    setMessage(null);
    setMobilePane("list");
    setPage(1);
    setSearch("");
    setRailOpen(false);
    setRefreshing(true);
    try {
      const f = await listFolders(address);
      setFolders(f);
      const newInbox = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
      setSelected(newInbox);
      loadList(newInbox, 1, "", address);
      // Refresh usage figures in the background — never block the switch on it.
      void getMailboxes()
        .then((mb) => setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []))
        .catch(() => {});
    } catch {
      setToast("Couldn't switch mailbox.");
    } finally {
      setRefreshing(false);
    }
  };

  const openMessage = (m: MessageSummary) => {
    setSelectedUid(m.uid);
    setCursorUid(m.uid);
    setMobilePane("read");
    setMsgLoading(true);
    // Optimistically mark as read.
    if (!m.seen) {
      setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, seen: true } : x)) }));
      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
      void setFlag(m.folder, m.uid, "seen", true, activeAddress).catch(() => {});
    }
    (async () => {
      try {
        const full = await getMessage(m.folder, m.uid, activeAddress);
        setMessage(full);
      } catch {
        setToast("Couldn't open this message.");
        setMessage(null);
      } finally {
        setMsgLoading(false);
      }
    })();
  };

  /* ---- Mutations -------------------------------------------------------- */
  const toggleStar = (m: MessageSummary | MessageFull) => {
    const next = !m.flagged;
    setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, flagged: next } : x)) }));
    setMessage((cur) => (cur && cur.uid === m.uid ? { ...cur, flagged: next } : cur));
    if (selected === STARRED && !next) {
      // Un-starring inside the Starred view removes the row.
      setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
    }
    void setFlag(m.folder, m.uid, "flagged", next, activeAddress).catch(() => setToast("Couldn't update star."));
  };

  const removeFromList = (m: MessageSummary | MessageFull) => {
    setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
    // Keep folder unread counts honest when an unread message leaves the folder.
    if (!m.seen) {
      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
    }
    setSelectedUid(null);
    setCursorUid(null);
    setMessage(null);
    setMobilePane("list");
  };

  const doArchive = () => {
    if (!message) return;
    const m = message;
    if (!archivePath || m.folder === archivePath) {
      setToast("No archive folder available.");
      return;
    }
    removeFromList(m);
    setToast("Message archived.");
    void moveMessage(m.folder, m.uid, archivePath, activeAddress).catch(() => setToast("Archive failed."));
  };

  const doDelete = () => {
    if (!message) return;
    const m = message;
    removeFromList(m);
    // If already in trash, hard-delete; otherwise move to trash when possible.
    if (trashPath && m.folder !== trashPath) {
      setToast("Moved to Trash.");
      void moveMessage(m.folder, m.uid, trashPath, activeAddress).catch(() => setToast("Delete failed."));
    } else {
      setToast("Message deleted.");
      void deleteMessage(m.folder, m.uid, activeAddress).catch(() => setToast("Delete failed."));
    }
  };

  const doMove = (toFolder: string) => {
    if (!message) return;
    const m = message;
    removeFromList(m);
    setToast(`Moved to ${labelFor(toFolder)}.`);
    void moveMessage(m.folder, m.uid, toFolder, activeAddress).catch(() => setToast("Move failed."));
  };

  /* ---- Compose / reply -------------------------------------------------- */
  const stripRe = (s: string) => s.replace(/^\s*(re|fwd?):\s*/i, "").trim();
  const quoteOf = (m: MessageFull) =>
    m.html ??
    (m.text ? `<pre style="white-space:pre-wrap">${m.text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>` : "");

  const openCompose = (to = "") =>
    setDraft({ mode: "new", to, cc: "", subject: "", body: "" });

  const openReply = (all: boolean) => {
    if (!message) return;
    const m = message;
    const selfAddr = mailbox?.address?.toLowerCase();
    const ccList = all
      ? [...m.to, ...m.cc].map((a) => a.address).filter((a) => a.toLowerCase() !== selfAddr && a.toLowerCase() !== m.from.address.toLowerCase())
      : [];
    setDraft({
      mode: all ? "replyAll" : "reply",
      to: m.from.address,
      cc: [...new Set(ccList)].join(", "),
      subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
      body: `\n\n`,
      quotedHtml: `<p>On ${new Date(m.date).toLocaleString()}, ${displayName(m.from)} wrote:</p>${quoteOf(m)}`,
      inReplyToUid: m.uid,
      replyFolder: m.folder,
    });
  };

  const openForward = () => {
    if (!message) return;
    const m = message;
    setDraft({
      mode: "forward",
      to: "",
      cc: "",
      subject: `Fwd: ${stripRe(m.subject) || "(no subject)"}`,
      body: `\n\n`,
      quotedHtml: `<p>---------- Forwarded message ----------<br>From: ${displayName(m.from)} &lt;${m.from.address}&gt;<br>Date: ${new Date(m.date).toLocaleString()}<br>Subject: ${m.subject}</p>${quoteOf(m)}`,
    });
  };

  const handleSend = async (payload: SendPayload) => {
    const res = await sendMessage(payload, activeAddress);
    if (res && res.ok === false) throw new Error(res.error || "The mail server rejected the message.");
    setToast("Message sent.");
    // If we're viewing Sent, refresh it.
    const sentPath = folders.find((f) => f.role === "sent")?.path;
    if (resolvePath(selected) === sentPath) loadList(selected, page, search);
  };

  const quickReply = async (text: string) => {
    if (!message) return;
    const m = message;
    try {
      await handleSend({
        to: m.from.address,
        subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
        text,
        html: `<div style="white-space:pre-wrap">${text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</div>`,
        inReplyToUid: m.uid,
        replyFolder: m.folder,
      });
      setMessage((cur) => (cur ? { ...cur, answered: true } : cur));
    } catch (e) {
      setToast(e instanceof Error ? e.message : "Reply failed.");
      throw e;
    }
  };

  /* ---- Search debounce -------------------------------------------------- */
  const onSearch = (s: string) => {
    setSearch(s);
    if (searchTimer.current) clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => {
      setPage(1);
      loadList(selected, 1, s);
    }, 350);
  };

  const onPage = (p: number) => {
    setPage(p);
    loadList(selected, p, search);
  };

  const onTab = (t: MailTab) => setTab(t);

  const refresh = async () => {
    setRefreshing(true);
    try {
      const [f, mb] = await Promise.all([listFolders(activeAddress), getMailboxes()]);
      setFolders(f);
      setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []);
      loadList(selected, page, search);
    } catch {
      setToast("Refresh failed.");
    } finally {
      setRefreshing(false);
    }
  };

  /* ---- Toast auto-dismiss ---------------------------------------------- */
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);

  /* ---- Keyboard shortcuts ---------------------------------------------- */
  // Messages currently visible in the list (after the category-tab filter),
  // used to move the j/k selection cursor.
  const visibleMessages = list.messages.filter((m) => categoryOf(m.from, m.subject) === tab);

  const scrollRowIntoView = (uid: number) => {
    requestAnimationFrame(() => {
      document.querySelector(`[data-mail-uid="${uid}"]`)?.scrollIntoView({ block: "nearest" });
    });
  };

  const moveCursor = (dir: 1 | -1) => {
    if (visibleMessages.length === 0) return;
    const curId = cursorUid ?? selectedUid;
    let idx = visibleMessages.findIndex((m) => m.uid === curId);
    if (idx === -1) idx = dir === 1 ? -1 : 0;
    const next = Math.max(0, Math.min(visibleMessages.length - 1, idx + dir));
    const target = visibleMessages[next];
    if (target) {
      setCursorUid(target.uid);
      scrollRowIntoView(target.uid);
    }
  };

  const openCursor = () => {
    const id = cursorUid ?? selectedUid;
    const m = visibleMessages.find((x) => x.uid === id);
    if (m) openMessage(m);
  };

  // A single always-current handler behind a stable ref so the window listener
  // is bound once yet never reads stale state.
  const keyHandlerRef = useRef<(e: KeyboardEvent) => void>(() => {});
  keyHandlerRef.current = (e: KeyboardEvent) => {
    if (showHelp) {
      if (e.key === "Escape" || e.key === "?") {
        e.preventDefault();
        setShowHelp(false);
      }
      return;
    }
    // The Composer owns its own keys while it's open.
    if (draft) return;

    const el = document.activeElement as HTMLElement | null;
    const typing =
      !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable);
    if (typing) {
      if (e.key === "Escape") el?.blur();
      return;
    }
    if (e.metaKey || e.ctrlKey || e.altKey) return;

    switch (e.key) {
      case "j": e.preventDefault(); moveCursor(1); break;
      case "k": e.preventDefault(); moveCursor(-1); break;
      case "Enter":
        // Let a focused button/link handle its own Enter instead of opening.
        if (el && (el.tagName === "BUTTON" || el.tagName === "A")) break;
        e.preventDefault();
        openCursor();
        break;
      case "o": e.preventDefault(); openCursor(); break;
      case "r": if (message) { e.preventDefault(); openReply(false); } break;
      case "a": if (message) { e.preventDefault(); openReply(true); } break;
      case "f": if (message) { e.preventDefault(); openForward(); } break;
      case "e": if (message) { e.preventDefault(); doArchive(); } break;
      case "#": if (message) { e.preventDefault(); doDelete(); } break;
      case "s": if (message) { e.preventDefault(); toggleStar(message); } break;
      case "c": e.preventDefault(); openCompose(); break;
      case "/": e.preventDefault(); document.getElementById("mail-search-input")?.focus(); break;
      case "?": e.preventDefault(); setShowHelp(true); break;
      case "Escape":
        e.preventDefault();
        setSelectedUid(null);
        setCursorUid(null);
        setMessage(null);
        setMobilePane("list");
        break;
      default: break;
    }
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => keyHandlerRef.current(e);
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  /* ---- Render ----------------------------------------------------------- */
  return (
    <div className="relative flex h-[calc(100vh-8rem)] min-h-[560px] overflow-hidden rounded-2xl border border-white/[0.06] bg-navy-900/60 backdrop-blur-md" style={{ boxShadow: "0 8px 32px -12px rgb(0 0 0 / 0.5)" }}>
      {/* Folder rail — static on md+, slide-over on mobile */}
      <aside className="hidden w-56 flex-none border-r border-white/[0.06] bg-navy-950/30 md:flex lg:w-60">
        <FolderRail
          primary={primaryItems.filter((i) => !i.key.startsWith("__missing_"))}
          custom={customItems}
          selected={selected}
          mailbox={mailbox}
          mailboxes={mailboxes}
          activeAddress={activeAddress}
          onSwitchMailbox={switchMailbox}
          onSelect={selectFolder}
          onCompose={() => openCompose()}
          onRefresh={refresh}
          refreshing={refreshing}
        />
      </aside>

      {/* Mobile rail drawer */}
      {railOpen && (
        <div className="absolute inset-0 z-40 md:hidden">
          <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={() => setRailOpen(false)} />
          <div className="absolute inset-y-0 left-0 w-64 border-r border-white/[0.06] bg-navy-900 shadow-2xl animate-fade-up">
            <FolderRail
              primary={primaryItems.filter((i) => !i.key.startsWith("__missing_"))}
              custom={customItems}
              selected={selected}
              mailbox={mailbox}
              mailboxes={mailboxes}
              activeAddress={activeAddress}
              onSwitchMailbox={switchMailbox}
              onSelect={selectFolder}
              onCompose={() => { setRailOpen(false); openCompose(); }}
              onRefresh={refresh}
              refreshing={refreshing}
            />
          </div>
        </div>
      )}

      {/* Message list */}
      <section className={`w-full flex-none border-r border-white/[0.06] md:w-80 lg:w-[22rem] ${mobilePane === "read" ? "hidden md:flex md:flex-col" : "flex flex-col"}`}>
        <MessageList
          title={labelFor(selected)}
          unread={folders.find((f) => f.path === resolvePath(selected))?.unread ?? 0}
          messages={list.messages}
          total={list.total}
          page={selected === STARRED ? 1 : page}
          pageSize={list.pageSize}
          loading={listPending}
          selectedUid={selectedUid}
          cursorUid={cursorUid}
          tab={tab}
          search={search}
          onTab={onTab}
          onSearch={onSearch}
          onSelect={openMessage}
          onToggleStar={toggleStar}
          onPage={onPage}
          onMenu={() => setRailOpen(true)}
        />
      </section>

      {/* Reading pane */}
      <section className={`min-w-0 flex-1 ${mobilePane === "list" ? "hidden md:flex md:flex-col" : "flex flex-col"}`}>
        <ReadingPane
          message={message}
          loading={msgLoading}
          folders={folders}
          currentFolder={message?.folder ?? ""}
          onReply={() => openReply(false)}
          onReplyAll={() => openReply(true)}
          onForward={openForward}
          onArchive={doArchive}
          onDelete={doDelete}
          onMove={doMove}
          onToggleStar={() => message && toggleStar(message)}
          onQuickReply={quickReply}
          onBack={() => { setMobilePane("list"); }}
        />
      </section>

      {/* Contact panel */}
      <aside className="hidden w-72 flex-none border-l border-white/[0.06] bg-navy-950/30 xl:block">
        <ContactPanel
          message={message}
          folderLabel={labelFor(selected)}
          currentFolder={message?.folder ?? ""}
          mailboxAddress={activeAddress}
          onCompose={openCompose}
          onOpenMessage={openMessage}
        />
      </aside>

      {/* Keyboard shortcut hint */}
      <button
        onClick={() => setShowHelp(true)}
        title="Keyboard shortcuts (?)"
        aria-label="Keyboard shortcuts"
        className="absolute bottom-3 right-3 z-30 hidden h-8 w-8 items-center justify-center rounded-full border border-white/10 bg-navy-900/80 text-sm font-semibold text-slate-400 shadow-lg backdrop-blur transition-colors hover:border-brand-400/40 hover:text-white md:flex"
      >
        ?
      </button>

      {/* Shortcut help modal */}
      {showHelp && <ShortcutHelp onClose={() => setShowHelp(false)} />}

      {/* Composer modal */}
      {draft && <Composer draft={draft} onClose={() => setDraft(null)} onSend={handleSend} />}

      {/* Toast */}
      {toast && (
        <div className="pointer-events-none absolute bottom-4 left-1/2 z-50 -translate-x-1/2">
          <div className="glass flex items-center gap-2 px-4 py-2.5 text-sm text-slate-100 shadow-2xl animate-fade-up">
            <span className="text-brand-300"><Icon.mail size={15} /></span>
            {toast}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import type { MailboxInfo } from "@/lib/mail/types";
import { Icon, type IconName, fmtBytesShort } from "./util";

export type RailItem = {
  key: string; // folder path or virtual sentinel
  label: string;
  icon: IconName;
  unread?: number;
  virtual?: boolean;
};

export function FolderRail({
  primary,
  custom,
  selected,
  mailbox,
  mailboxes,
  activeAddress,
  onSwitchMailbox,
  onSelect,
  onCompose,
  onRefresh,
  refreshing,
}: {
  primary: RailItem[];
  custom: RailItem[];
  selected: string;
  mailbox: MailboxInfo | null;
  mailboxes: MailboxInfo[];
  activeAddress?: string;
  onSwitchMailbox: (address: string) => void;
  onSelect: (key: string) => void;
  onCompose: () => void;
  onRefresh: () => void;
  refreshing: boolean;
}) {
  const usedPct = mailbox && mailbox.quotaBytes > 0
    ? Math.min(100, Math.round((mailbox.usedBytes / mailbox.quotaBytes) * 100))
    : 0;
  const nearFull = usedPct >= 85;

  return (
    <div className="flex h-full flex-col">
      {/* Mailbox switcher / label */}
      {mailboxes.length > 0 && (
        <div className="border-b border-white/[0.06] p-3 pb-2.5">
          <MailboxSwitcher
            mailboxes={mailboxes}
            activeAddress={activeAddress ?? mailbox?.address}
            onSwitch={onSwitchMailbox}
          />
        </div>
      )}

      {/* Compose */}
      <div className="p-3">
        <button onClick={onCompose} className="btn-primary w-full">
          <Icon.compose size={16} />
          Compose
        </button>
      </div>

      <nav className="flex-1 space-y-1 overflow-y-auto px-2 pb-3">
        {primary.map((it) => (
          <RailButton key={it.key} item={it} active={selected === it.key} onClick={() => onSelect(it.key)} />
        ))}

        {custom.length > 0 && (
          <>
            <p className="section-label px-3 pb-1 pt-4">Folders</p>
            {custom.map((it) => (
              <RailButton key={it.key} item={it} active={selected === it.key} onClick={() => onSelect(it.key)} />
            ))}
          </>
        )}

        <p className="section-label px-3 pb-1 pt-4">Tools</p>
        <button
          onClick={onRefresh}
          className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white"
        >
          <Icon.refresh size={17} className={refreshing ? "animate-spin text-brand-300" : ""} />
          Refresh
        </button>
        <a
          href="/dashboard/email"
          className="flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white"
        >
          <Icon.cog size={17} />
          Mail settings
        </a>
        <button
          disabled
          title="Filters — coming soon"
          className="flex w-full cursor-not-allowed items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-600"
        >
          <Icon.filter size={17} />
          Filters
        </button>
      </nav>

      {/* Storage bar */}
      <div className="border-t border-white/[0.06] p-3">
        <div className="mb-1.5 flex items-center justify-between text-[11px]">
          <span className="font-medium text-slate-400">Storage</span>
          <span className={nearFull ? "text-amber-300" : "text-slate-500"}>
            {mailbox ? `${fmtBytesShort(mailbox.usedBytes)} / ${fmtBytesShort(mailbox.quotaBytes)}` : "—"}
          </span>
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className={`h-full rounded-full transition-all ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
            style={{ width: `${usedPct}%` }}
          />
        </div>
        {mailbox && (
          <p className="mt-1.5 truncate text-[11px] text-slate-600" title={mailbox.address}>
            {mailbox.address}
          </p>
        )}
      </div>
    </div>
  );
}

function MailboxSwitcher({
  mailboxes,
  activeAddress,
  onSwitch,
}: {
  mailboxes: MailboxInfo[];
  activeAddress?: string;
  onSwitch: (address: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const current = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0];

  // Single mailbox: static, non-interactive label.
  if (mailboxes.length <= 1) {
    return (
      <div className="flex items-center gap-2 rounded-xl border border-white/10 bg-navy-900/60 px-3 py-2">
        <Icon.mail size={15} className="flex-none text-brand-300" />
        <span className="truncate text-xs font-medium text-slate-300" title={current?.address}>
          {current?.address ?? "Mailbox"}
        </span>
      </div>
    );
  }

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center gap-2 rounded-xl border border-white/10 bg-navy-900/60 px-3 py-2 text-left transition-colors hover:border-brand-400/40 hover:bg-navy-900/80"
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <Icon.mail size={15} className="flex-none text-brand-300" />
        <span className="min-w-0 flex-1 truncate text-xs font-medium text-slate-200" title={current?.address}>
          {current?.address ?? "Select mailbox"}
        </span>
        <span className={`flex-none text-slate-500 transition-transform ${open ? "rotate-180" : ""}`}>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden><path d="m6 9 6 6 6-6" /></svg>
        </span>
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className="glass absolute left-0 right-0 top-12 z-20 max-h-72 overflow-y-auto py-1.5 shadow-2xl" role="listbox">
            <p className="section-label px-3 py-1">Mailboxes</p>
            {mailboxes.map((m) => {
              const active = m.address === current?.address;
              return (
                <button
                  key={m.address}
                  role="option"
                  aria-selected={active}
                  onClick={() => {
                    setOpen(false);
                    if (!active) onSwitch(m.address);
                  }}
                  className={`flex w-full items-center gap-2.5 px-3 py-2 text-left text-sm transition-colors ${
                    active ? "text-white" : "text-slate-300 hover:bg-white/[0.05] hover:text-white"
                  }`}
                >
                  <Icon.mail size={14} className={active ? "flex-none text-brand-300" : "flex-none text-slate-500"} />
                  <span className="min-w-0 flex-1 truncate">{m.address}</span>
                  {active && (
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" className="flex-none text-brand-300" aria-hidden><path d="M20 6 9 17l-5-5" /></svg>
                  )}
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

function RailButton({ item, active, onClick }: { item: RailItem; active: boolean; onClick: () => void }) {
  const Ico = Icon[item.icon];
  return (
    <button
      onClick={onClick}
      className={`flex w-full items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
        active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
      }`}
    >
      <Ico size={17} className={active ? "text-white" : ""} />
      <span className="flex-1 truncate text-left">{item.label}</span>
      {item.unread ? (
        <span
          className={`flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold ${
            active ? "bg-white/25 text-white" : "bg-brand-500/90 text-white"
          }`}
        >
          {item.unread > 99 ? "99+" : item.unread}
        </span>
      ) : null}
    </button>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { MessageFull, MessageSummary } from "@/lib/mail/types";
import { listMessages } from "@/lib/actions-mail";
import { Icon, initials, displayName, avatarGradient, categoryOf, shortDate } from "./util";

export function ContactPanel({
  message,
  folderLabel,
  currentFolder,
  mailboxAddress,
  onCompose,
  onOpenMessage,
}: {
  message: MessageFull | null;
  folderLabel: string;
  currentFolder: string;
  mailboxAddress?: string;
  onCompose: (to: string) => void;
  onOpenMessage: (m: MessageSummary) => void;
}) {
  const [related, setRelated] = useState<MessageSummary[]>([]);

  // Load recent messages from the same sender. Fail soft — the section simply
  // stays hidden when the search errors or returns nothing.
  const senderAddress = message?.from.address;
  const openUid = message?.uid;
  useEffect(() => {
    if (!senderAddress || !currentFolder) {
      setRelated([]);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const res = await listMessages(currentFolder, 1, senderAddress, mailboxAddress);
        if (cancelled) return;
        const items = res.messages
          .filter(
            (m) => m.uid !== openUid && m.from.address.toLowerCase() === senderAddress.toLowerCase(),
          )
          .slice(0, 5);
        setRelated(items);
      } catch {
        if (!cancelled) setRelated([]);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [senderAddress, openUid, currentFolder, mailboxAddress]);

  if (!message) {
    return (
      <div className="flex h-full flex-col items-center justify-center px-5 text-center">
        <div className="mb-3 rounded-2xl border border-white/[0.08] bg-white/[0.03] p-3.5 text-slate-500">
          <Icon.user size={24} />
        </div>
        <p className="text-sm font-medium text-slate-400">Contact details</p>
        <p className="mt-1 text-xs text-slate-600">Open a message to see who it's from.</p>
      </div>
    );
  }

  const from = message.from;
  const category = categoryOf(from, message.subject);
  const domain = from.address.split("@")[1] ?? "";

  // Lightweight, honest "tags" derived from the message itself.
  const tags: string[] = [folderLabel];
  tags.push(category === "primary" ? "Primary" : category === "promotions" ? "Promotions" : "Social");
  if (message.hasAttachments) tags.push("Has files");
  if (message.flagged) tags.push("Starred");
  if (message.answered) tags.push("Replied");

  return (
    <div className="flex h-full flex-col overflow-y-auto">
      {/* Contact header */}
      <div className="flex flex-col items-center border-b border-white/[0.06] px-5 pb-5 pt-6 text-center">
        <div
          className={`flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br text-xl font-bold text-white ${avatarGradient(
            from.address
          )}`}
        >
          {initials(from)}
        </div>
        <p className="mt-3 text-base font-semibold text-white">{displayName(from)}</p>
        <p className="mt-0.5 max-w-full truncate text-xs text-slate-500" title={from.address}>
          {from.address}
        </p>

        <button onClick={() => onCompose(from.address)} className="btn-secondary mt-4 w-full">
          <Icon.compose size={15} />
          New email
        </button>
      </div>

      {/* Details */}
      <div className="space-y-5 px-5 py-5">
        <Field label="Email">
          <a href={`mailto:${from.address}`} className="break-all text-brand-300 hover:text-brand-200">
            {from.address}
          </a>
        </Field>
        {domain && <Field label="Domain">{domain}</Field>}
        <Field label="Recipients">
          {message.to.length + message.cc.length} recipient
          {message.to.length + message.cc.length === 1 ? "" : "s"}
        </Field>

        {/* Tags */}
        <div>
          <p className="section-label mb-2">Tags</p>
          <div className="flex flex-wrap gap-1.5">
            {tags.map((t) => (
              <span
                key={t}
                className="inline-flex items-center gap-1 rounded-full border border-brand-500/30 bg-brand-500/10 px-2.5 py-0.5 text-[11px] font-medium text-brand-200"
              >
                <Icon.tag size={11} />
                {t}
              </span>
            ))}
          </div>
        </div>

        {/* Attachments recap */}
        {message.attachments.length > 0 && (
          <div>
            <p className="section-label mb-2">Attachments ({message.attachments.length})</p>
            <ul className="space-y-1.5">
              {message.attachments.map((a) => (
                <li key={a.id} className="flex items-center gap-2 text-xs text-slate-400">
                  <Icon.paperclip size={12} className="flex-none text-slate-500" />
                  <span className="truncate">{a.filename}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Related conversations from the same sender */}
        {related.length > 0 && (
          <div>
            <p className="section-label mb-2">Related conversations</p>
            <ul className="space-y-1">
              {related.map((m) => (
                <li key={`${m.folder}:${m.uid}`}>
                  <button
                    onClick={() => onOpenMessage(m)}
                    className="group flex w-full items-start gap-2 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-white/[0.05]"
                  >
                    <span className="mt-0.5 flex-none text-slate-500 group-hover:text-brand-300">
                      <Icon.mail size={12} />
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className={`block truncate text-xs ${m.seen ? "text-slate-300" : "font-semibold text-white"}`}>
                        {m.subject || "(no subject)"}
                      </span>
                      <span className="mt-0.5 block text-[11px] text-slate-500">{shortDate(m.date)}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="section-label mb-1">{label}</p>
      <div className="text-sm text-slate-300">{children}</div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { MessageFull, MailFolder } from "@/lib/mail/types";
import {
  Icon,
  initials,
  displayName,
  avatarGradient,
  fullDate,
  joinAddresses,
  fmtBytesShort,
} from "./util";

export function ReadingPane({
  message,
  loading,
  folders,
  currentFolder,
  onReply,
  onReplyAll,
  onForward,
  onArchive,
  onDelete,
  onMove,
  onToggleStar,
  onQuickReply,
  onBack,
}: {
  message: MessageFull | null;
  loading: boolean;
  folders: MailFolder[];
  currentFolder: string;
  onReply: () => void;
  onReplyAll: () => void;
  onForward: () => void;
  onArchive: () => void;
  onDelete: () => void;
  onMove: (toFolder: string) => void;
  onToggleStar: () => void;
  onQuickReply: (text: string) => Promise<void>;
  onBack: () => void;
}) {
  const [moveOpen, setMoveOpen] = useState(false);
  const [quick, setQuick] = useState("");
  const [sending, setSending] = useState(false);

  useEffect(() => {
    setQuick("");
    setMoveOpen(false);
  }, [message?.uid, message?.folder]);

  if (loading) return <ReadingSkeleton onBack={onBack} />;

  if (!message) {
    return (
      <div className="flex h-full flex-col items-center justify-center px-6 text-center">
        <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-5 text-brand-300">
          <Icon.mail size={34} />
        </div>
        <p className="text-base font-semibold text-slate-200">Select a message</p>
        <p className="mt-1 max-w-xs text-sm text-slate-500">
          Pick a conversation from the list to read it here.
        </p>
      </div>
    );
  }

  const submitQuick = async () => {
    const text = quick.trim();
    if (!text || sending) return;
    setSending(true);
    try {
      await onQuickReply(text);
      setQuick("");
    } finally {
      setSending(false);
    }
  };

  const moveTargets = folders.filter((f) => f.path !== currentFolder);

  return (
    <div className="flex h-full flex-col">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-1 border-b border-white/[0.06] px-3 py-2.5">
        <button onClick={onBack} className="btn-ghost mr-1 rounded-lg p-2 lg:hidden" aria-label="Back to list">
          <Icon.chevronLeft size={18} />
        </button>
        <ToolBtn label="Archive" onClick={onArchive}><Icon.archive size={17} /></ToolBtn>
        <ToolBtn label="Delete" onClick={onDelete} danger><Icon.trash size={17} /></ToolBtn>
        <ToolBtn label="Snooze" disabled title="Snooze — coming soon"><Icon.clock size={17} /></ToolBtn>

        {/* Move dropdown */}
        <div className="relative">
          <ToolBtn label="Move" onClick={() => setMoveOpen((v) => !v)}><Icon.move size={17} /></ToolBtn>
          {moveOpen && (
            <>
              <div className="fixed inset-0 z-10" onClick={() => setMoveOpen(false)} />
              <div className="glass absolute left-0 top-11 z-20 max-h-72 w-56 overflow-y-auto py-1.5 shadow-2xl">
                <p className="section-label px-3 py-1">Move to</p>
                {moveTargets.map((f) => (
                  <button
                    key={f.path}
                    onClick={() => {
                      setMoveOpen(false);
                      onMove(f.path);
                    }}
                    className="flex w-full items-center gap-2.5 px-3 py-2 text-left text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white"
                  >
                    <Icon.folder size={15} className="text-slate-500" />
                    <span className="truncate">{f.name}</span>
                  </button>
                ))}
              </div>
            </>
          )}
        </div>

        <div className="mx-1 h-6 w-px bg-white/[0.08]" />

        <ToolBtn label="Reply" onClick={onReply}><Icon.reply size={17} /></ToolBtn>
        <ToolBtn label="Reply all" onClick={onReplyAll}><Icon.replyAll size={17} /></ToolBtn>
        <ToolBtn label="Forward" onClick={onForward}><Icon.forward size={17} /></ToolBtn>

        <button
          onClick={onToggleStar}
          className={`btn-ghost ml-auto rounded-lg p-2 ${message.flagged ? "text-amber-400" : ""}`}
          aria-label={message.flagged ? "Unstar" : "Star"}
        >
          {message.flagged ? <Icon.starFilled size={17} /> : <Icon.star size={17} />}
        </button>
      </div>

      {/* Scroll body */}
      <div className="flex-1 overflow-y-auto">
        <div className="px-5 py-5 sm:px-7">
          <h1 className="text-xl font-bold leading-snug tracking-tight text-white sm:text-2xl">
            {message.subject || "(no subject)"}
          </h1>

          {/* Sender line */}
          <div className="mt-4 flex items-start gap-3">
            <div
              className={`flex h-11 w-11 flex-none items-center justify-center rounded-full bg-gradient-to-br text-sm font-bold text-white ${avatarGradient(
                message.from.address
              )}`}
            >
              {initials(message.from)}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-baseline gap-x-2">
                <span className="text-sm font-semibold text-white">{displayName(message.from)}</span>
                <span className="truncate text-xs text-slate-500">&lt;{message.from.address}&gt;</span>
              </div>
              <p className="mt-0.5 text-xs text-slate-500">
                to {joinAddresses(message.to)}
                {message.cc.length > 0 && <>, cc {joinAddresses(message.cc)}</>}
              </p>
            </div>
            <span className="flex-none whitespace-nowrap pt-0.5 text-xs text-slate-500">
              {fullDate(message.date)}
            </span>
          </div>

          {/* Attachments */}
          {message.attachments.length > 0 && (
            <div className="mt-4 flex flex-wrap gap-2">
              {message.attachments.map((att) => (
                <a
                  key={att.id}
                  href={`/api/mail/attachment?folder=${encodeURIComponent(message.folder)}&uid=${message.uid}&part=${encodeURIComponent(att.id)}`}
                  className="group flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-sm transition-colors hover:border-brand-500/30 hover:bg-white/[0.06]"
                >
                  <span className="text-brand-300">
                    <Icon.paperclip size={16} />
                  </span>
                  <span className="min-w-0">
                    <span className="block max-w-[12rem] truncate text-slate-200 group-hover:text-white">{att.filename}</span>
                    <span className="block text-[11px] text-slate-500">{fmtBytesShort(att.sizeBytes)}</span>
                  </span>
                </a>
              ))}
            </div>
          )}

          <div className="divider" />

          {/* Body */}
          <MessageBody html={message.html} text={message.text} />
        </div>
      </div>

      {/* Quick reply */}
      <div className="border-t border-white/[0.06] bg-navy-900/40 p-3">
        <div className="flex items-end gap-2 rounded-xl border border-white/10 bg-navy-900/80 p-2 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
          <div className={`hidden h-8 w-8 flex-none items-center justify-center rounded-full bg-gradient-to-br text-xs font-bold text-white sm:flex ${avatarGradient(message.from.address)}`}>
            <Icon.reply size={15} />
          </div>
          <textarea
            value={quick}
            onChange={(e) => setQuick(e.target.value)}
            onKeyDown={(e) => {
              if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
                e.preventDefault();
                void submitQuick();
              }
            }}
            rows={1}
            placeholder={`Quick reply to ${displayName(message.from)}…`}
            className="max-h-32 min-h-[2.25rem] flex-1 resize-none bg-transparent py-1.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
          />
          <button
            onClick={submitQuick}
            disabled={!quick.trim() || sending}
            className="btn-primary flex-none px-3 py-2"
          >
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
        <p className="mt-1 px-1 text-[11px] text-slate-600">
          Press <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span> to send
        </p>
      </div>
    </div>
  );
}

/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
 *  reach cookies/storage. Plaintext falls back to a pre block. */
function MessageBody({ html, text }: { html: string | null; text: string | null }) {
  const ref = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState(320);

  const doc = html
    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
        body{padding:16px;}
        img{max-width:100%;height:auto;}
        a{color:#5f2ee8;}
        table{max-width:100%;}
        pre{white-space:pre-wrap;}
        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
      </style></head><body>${html}</body></html>`
    : null;

  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
  // grow to a comfortable default and let the iframe scroll for very tall mail.
  useEffect(() => {
    setHeight(html ? 480 : 0);
  }, [html]);

  if (doc) {
    return (
      <iframe
        ref={ref}
        sandbox=""
        srcDoc={doc}
        title="Message content"
        className="w-full rounded-xl border border-white/[0.06] bg-white"
        style={{ height }}
      />
    );
  }

  if (text && text.trim()) {
    return (
      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
        {text}
      </pre>
    );
  }

  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
}

function ToolBtn({
  children,
  label,
  onClick,
  danger,
  disabled,
  title,
}: {
  children: React.ReactNode;
  label: string;
  onClick?: () => void;
