import { redirect } from "next/navigation";
import { currentUser, impersonating } from "@/lib/auth";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { Shell, type NavSection } from "@/components/portal/Shell";

/** Hrefs hidden from the customer nav when their feature flag is off. */
const FEATURE_HREF: Record<string, string> = {
  "/dashboard/games": "feature_game_servers",
  "/dashboard/build": "feature_claude_builder",
  "/dashboard/domains": "feature_domains",
  "/dashboard/refer": "feature_referrals",
  "/dashboard/affiliate": "feature_referrals",
};

const nav: NavSection[] = [
  {
    items: [{ label: "Dashboard", href: "/dashboard", icon: "home" }],
  },
  {
    label: "Compute",
    items: [
      { label: "Servers", href: "/dashboard/servers", icon: "server" },
      { label: "Deploy", href: "/dashboard/deploy", icon: "rocket" },
      { label: "Migrate here", href: "/dashboard/migrate", icon: "rocket" },
      { label: "Game servers", href: "/dashboard/games", icon: "server" },
      { label: "Volumes", href: "/dashboard/volumes", icon: "db" },
      { label: "Build with AI", href: "/dashboard/build", icon: "bolt" },
      { label: "Claude Code", href: "/dashboard/claude-code", icon: "rocket" },
    ],
  },
  {
    label: "Network",
    items: [
      { label: "Domains", href: "/dashboard/domains", icon: "globe" },
      { label: "Mail", href: "/dashboard/mail", icon: "chat" },
      { label: "Business email", href: "/dashboard/email", icon: "chat" },
      { label: "SSL certificates", href: "/dashboard/ssl", icon: "shield" },
    ],
  },
  {
    label: "Tools",
    items: [{ label: "Free tools", href: "/tools", icon: "bolt" }],
  },
  {
    label: "Account",
    items: [
      { label: "Billing", href: "/dashboard/billing", icon: "card" },
      { label: "Invoices", href: "/dashboard/invoices", icon: "card" },
      { label: "Refer & earn", href: "/dashboard/refer", icon: "rocket" },
      { label: "Affiliate", href: "/dashboard/affiliate", icon: "dollar" },
      { label: "Team", href: "/dashboard/team", icon: "users" },
      { label: "Support", href: "/dashboard/support", icon: "chat" },
      { label: "Feedback", href: "/dashboard/feedback", icon: "chat" },
      { label: "Activity", href: "/dashboard/activity", icon: "pulse" },
      { label: "Settings", href: "/dashboard/settings", icon: "cog" },
    ],
  },
];

export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) redirect("/login");
  const imp = await impersonating();

  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
  // admins impersonating a customer) always pass so they can keep working. This
  // only covers the dashboard tree — /login and /admin have their own layouts.
  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
    const message = await getSetting("maintenance_message");
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "1rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
      </main>
    );
  }

  // Hide nav entries whose feature flag is disabled (secondary to the server-side
  // refusals in the order/create actions).
  const flags: Record<string, boolean> = {
    feature_game_servers: await getSettingBool("feature_game_servers", true),
    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
    feature_domains: await getSettingBool("feature_domains", true),
    feature_referrals: await getSettingBool("feature_referrals", true),
  };
  const visibleNav: NavSection[] = nav
    .map((section) => ({
      ...section,
      items: section.items.filter((item) => {
        const flag = FEATURE_HREF[item.href];
        return !flag || flags[flag];
      }),
    }))
    .filter((section) => section.items.length > 0);

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Support badge: this customer's own tickets awaiting a staff reply
  // (their newly opened tickets + threads where they replied last). Fails soft.
  const supportAwaiting = await db.ticket
    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
    .catch(() => 0);
  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
    ...section,
    items: section.items.map((item) =>
      item.href === "/dashboard/support" && supportAwaiting > 0
        ? { ...item, badge: supportAwaiting }
        : item
    ),
  }));

  return (
    <Shell
      nav={navWithBadges}
      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
      impersonation={imp ? { adminName: imp.admin.name, targetEmail: imp.target.email } : null}
    >
      {children}
    </Shell>
  );
}
